  if (音節.介音 === 'w') 音節.聲母 = 音節.聲母.replace('ɰ', '');
  if (音節.韻基[0] === 'u') 音節.介音 = 音節.介音.replace('w', '');
  音節.韻母 = 音節.介音 + 音節.韻基;
