  // 流攝脣音入遇攝字
  調整('明母 侯韻 上聲', { 韻: '模' }); // 母某牡畝（謀戊在《廣韻》中涉及的字太多，不加入）
  if (層次 === 0) 調整('尤韻 並母 平上聲', { 韻: '虞' }); // 浮、婦阜負（《中原音韻》僅魚模，元曲押魚模、尤侯）
  調整('尤韻 幫滂母 去聲', { 韻: '虞' }); // 富、副

  // 蟹攝二等入假攝字
